    'nav.stress': { en: 'Stress Lab', hi: 'Stress Lab', it: 'Stress Lab', es: 'Lab de estrés', zh: '壓力測試', pt: 'Lab de estresse', fr: 'Labo de stress', ar: 'مختبر الضغط', de: 'Stresslabor', nl: 'Stresslab', ja: 'ストレスラボ', ko: '스트레스 랩', ru: 'Стресс-лаборатория', tr: 'Stres laboratuvarı' },
