    'arena.env_chip': { en: '🛡 Envelope armed — {n} rules gate your opens.', hi: '🛡 Envelope armed — {n} नियम आपके opens की जाँच करते हैं।', it: '🛡 Envelope attivo — {n} regole filtrano le tue aperture.', es: '🛡 Envelope armado — {n} reglas filtran tus aperturas.', zh: '🛡 Envelope 已啟用 — {n} 條規則把關你的開倉。', pt: '🛡 Envelope armado — {n} regras filtram suas aberturas.', fr: '🛡 Envelope armé — {n} règles filtrent vos ouvertures.', de: '🛡 Envelope scharf — {n} Regeln prüfen deine Orders.', nl: '🛡 Envelope actief — {n} regels bewaken je openingen.', ja: '🛡 Envelope 有効 — {n} 件のルールが建玉を審査します。', ko: '🛡 Envelope 장착됨 — {n}개 규칙이 진입을 심사합니다.', ru: '🛡 Envelope активен — {n} правил проверяют ваши входы.', tr: '🛡 Envelope etkin — {n} kural açılışlarınızı denetler.', ar: '🛡 الـ Envelope مفعّل — {n} قواعد تتحكم في فتحاتك.' },
    'arena.env_edit': { en: 'manage', hi: 'प्रबंधित करें', it: 'gestisci', es: 'gestionar', zh: '管理', pt: 'gerenciar', fr: 'gérer', de: 'verwalten', nl: 'beheren', ja: '管理', ko: '관리', ru: 'управлять', tr: 'yönet', ar: 'إدارة' },
