    // Arena DYNAMIC strings (built in JS): {x} placeholders are filled client-side.
    'arena.d_tape_pulse': { en: '{n} traders · {m} closes in 24h', hi: '{n} ट्रेडर · 24h में {m} क्लोज़', it: '{n} trader · {m} chiusure in 24h', es: '{n} traders · {m} cierres en 24h', zh: '{n} 位交易者 · 24小時內 {m} 筆平倉', pt: '{n} traders · {m} fechamentos em 24h', fr: '{n} traders · {m} clôtures en 24h', ar: '{n} متداولًا · {m} إغلاقًا خلال 24 ساعة', de: '{n} Trader · {m} Abschlüsse in 24 Std.', nl: '{n} traders · {m} sluitingen in 24 uur', ja: '{n} トレーダー · 24時間で {m} 件の決済', ko: '트레이더 {n}명 · 24시간 청산 {m}건', ru: '{n} трейдеров · {m} закрытий за 24 ч', tr: '{n} yatırımcı · 24 saatte {m} kapanış' },
