    'arena.d_reason_liq': { en: '💀 liquidated', hi: '💀 लिक्विडेटेड', it: '💀 liquidata', es: '💀 liquidado', zh: '💀 爆倉', pt: '💀 liquidado', fr: '💀 liquidé', ar: '💀 مُصفّى', de: '💀 liquidiert', nl: '💀 geliquideerd', ja: '💀 清算', ko: '💀 청산', ru: '💀 ликвидация', tr: '💀 likide edildi' },
