    'arena.f_max_lev': { en: 'Rule: max leverage', hi: 'नियम: अधिकतम लीवरेज', it: 'Regola: leva massima', es: 'Regla: apalancamiento máximo', zh: '規則：最高槓桿', pt: 'Regra: alavancagem máxima', fr: 'Règle : levier maximum', de: 'Regel: maximaler Hebel', nl: 'Regel: maximale hefboom', ja: 'ルール：最大レバレッジ', ko: '규칙: 최대 레버리지', ru: 'Правило: макс. плечо', tr: 'Kural: maksimum kaldıraç', ar: 'قاعدة: أقصى رافعة' },
