    'acc.pw_title': { en: 'Change password', hi: 'पासवर्ड बदलें', it: 'Cambia password', es: 'Cambiar contraseña', zh: '變更密碼', pt: 'Alterar palavra-passe', fr: 'Changer de mot de passe', de: 'Passwort ändern', nl: 'Wachtwoord wijzigen', ja: 'パスワードを変更', ko: '비밀번호 변경', ru: 'Сменить пароль', tr: 'Parolayı değiştir', ar: 'تغيير كلمة المرور' },
