    'esc.l.lp': { en: 'LP position', hi: 'LP पोज़िशन', it: 'posizione LP', es: 'posición LP', zh: 'LP 部位', pt: 'posição LP', fr: 'position LP', de: 'LP-Position', nl: 'LP-positie', ja: 'LP ポジション', ko: 'LP 포지션', ru: 'LP-позиция', tr: 'LP pozisyonu', ar: 'مركز سيولة' },
