    'sw.build': { en: "Preflight & build", hi: "प्रीफ़्लाइट और निर्माण", it: "Verifica e costruisci", es: "Comprobar y construir", zh: "預檢並建立", pt: "Pré-verificar e construir", fr: "Contrôler et construire", ar: "افحص وابنِ", de: "Vorprüfen & erstellen", nl: "Controleren en bouwen", ja: "事前チェックして構築", ko: "사전 점검 후 생성", ru: "Проверить и собрать", tr: "Ön kontrol ve oluştur" },
    'sw.c_net': { en: "Mode", hi: "मोड", it: "Modalità", es: "Modo", zh: "模式", pt: "Modo", fr: "Mode", ar: "الوضع", de: "Modus", nl: "Modus", ja: "モード", ko: "모드", ru: "Режим", tr: "Mod" },
    'sw.c_in': { en: "You pay", hi: "आप देते हैं", it: "Paghi", es: "Pagas", zh: "你支付", pt: "Você paga", fr: "Vous payez", ar: "تدفع", de: "Du zahlst", nl: "Je betaalt", ja: "支払い", ko: "지불", ru: "Вы платите", tr: "Ödediğiniz" },
